void contract_names() {
    using apex::render::Backend;
    using apex::render::DeviceStatus;
    require(std::string(apex::render::backend_name(Backend::Vulkan)) == "Vulkan", "Vulkan backend name");
    require(std::string(apex::render::backend_name(Backend::D3D12)) == "Direct3D 12", "D3D12 backend name");
    require(std::string(apex::render::device_status_name(DeviceStatus::ready)) == "ready", "ready status name");
    require(std::string(apex::render::device_status_name(DeviceStatus::unavailable)) == "unavailable", "unavailable status name");
    require(std::string(apex::render::buffer_status_name(apex::render::BufferStatus::ready)) == "ready",
            "buffer ready status name");
    require(std::string(apex::render::buffer_status_name(apex::render::BufferStatus::upload_failed)) == "upload_failed",
            "buffer upload status name");
    require(std::string(apex::render::texture_status_name(apex::render::TextureStatus::ready)) == "ready",
            "texture ready status name");
    require(std::string(apex::render::texture_status_name(apex::render::TextureStatus::upload_failed)) == "upload_failed",
            "texture upload status name");
    require(std::string(apex::render::texture_readback_status_name(
                apex::render::TextureReadbackStatus::execution_failed)) == "execution_failed",
            "texture readback status name");
    require(std::string(apex::render::triangle_draw_status_name(
                apex::render::TriangleDrawStatus::execution_failed)) == "execution_failed",
            "triangle draw status name");
    require(std::string(apex::render::sampler_status_name(apex::render::SamplerStatus::ready)) == "ready",
            "sampler ready status name");
    require(std::string(apex::render::shader_module_status_name(apex::render::ShaderModuleStatus::unsupported)) ==
                "unsupported",
            "shader unsupported status name");
    require(std::string(apex::render::presentation_target_status_name(
                apex::render::PresentationTargetStatus::invalid_description)) ==
                "invalid_description",
            "presentation invalid-description status name");
}

void contract_options() {
    using namespace apex::render;
    DeviceOptions options;
    options.headless = false;
    const AdapterResult adapters = enumerate_adapters(Backend::Vulkan, options);
    const DeviceResult device = create_device(Backend::Vulkan, options);
    require(adapters.status == DeviceStatus::invalid_options, "adapter invalid-options status");
    require(device.status == DeviceStatus::invalid_options, "device invalid-options status");
    require(adapters.diagnostic.code == "native_surface_required", "adapter native-surface diagnostic");
    require(device.diagnostic.code == "native_surface_required", "device native-surface diagnostic");

    apex::platform::NativeSurfaceSource source;
    source.vulkanInstanceExtensions = {"VK_KHR_surface"};
    options.native_surface = source;
    options.headless = true;
    require(enumerate_adapters(Backend::Vulkan, options).diagnostic.code ==
                "presentation_mode_conflict",
            "headless/native presentation mode conflict");
    require(create_device(Backend::Vulkan, options).diagnostic.code ==
                "presentation_mode_conflict",
            "device headless/native presentation mode conflict");

    options.headless = false;
    options.native_surface = source;
    require(enumerate_adapters(Backend::D3D12, options).status == DeviceStatus::invalid_options &&
                enumerate_adapters(Backend::D3D12, options).diagnostic.code ==
                    "d3d12_native_window_required",
            "D3D12 native presentation requires a Win32 window");
    require(create_device(Backend::D3D12, options).status == DeviceStatus::invalid_options &&
                create_device(Backend::D3D12, options).diagnostic.code ==
                    "d3d12_native_window_required",
            "D3D12 native device creation requires a Win32 window");
#if defined(_WIN32)
    source.win32Window = reinterpret_cast<void*>(static_cast<std::uintptr_t>(1U));
    options.native_surface = source;
    require(enumerate_adapters(Backend::D3D12, options).status == DeviceStatus::invalid_options &&
                enumerate_adapters(Backend::D3D12, options).diagnostic.code ==
                    "d3d12_native_window_invalid",
            "D3D12 rejects an invalid Win32 window during adapter validation");
    require(create_device(Backend::D3D12, options).status == DeviceStatus::invalid_options &&
                create_device(Backend::D3D12, options).diagnostic.code ==
                    "d3d12_native_window_invalid",
            "D3D12 rejects an invalid Win32 window during device validation");
    source.win32Window = nullptr;
#endif

    source.createVulkanSurface = contract_native_surface_create;
    source.destroyVulkanSurface = contract_native_surface_destroy;
    source.createVulkanSurface = nullptr;
    options.native_surface = source;
    require(enumerate_adapters(Backend::Vulkan, options).diagnostic.code ==
                "native_surface_callbacks_missing",
            "native surface create callback required");
    source.createVulkanSurface = contract_native_surface_create;
    source.destroyVulkanSurface = nullptr;
    options.native_surface = source;
    require(create_device(Backend::Vulkan, options).diagnostic.code ==
                "native_surface_callbacks_missing",
            "native surface destroy callback required");
    source.destroyVulkanSurface = contract_native_surface_destroy;
    source.vulkanInstanceExtensions.clear();
    options.native_surface = source;
    require(enumerate_adapters(Backend::Vulkan, options).diagnostic.code ==
                "native_surface_extensions_invalid",
            "native surface extension list required");
    source.vulkanInstanceExtensions = {"VK_KHR_surface", "VK_KHR_surface"};
    options.native_surface = source;
    require(create_device(Backend::Vulkan, options).diagnostic.code ==
                "native_surface_extension_duplicate",
            "native surface extension list must be unique");
    source.vulkanInstanceExtensions = {"VK_KHR_surface"};
    for (std::size_t index = 1U; index <= 64U; ++index)
        source.vulkanInstanceExtensions.push_back("VK_EXT_contract_" + std::to_string(index));
    options.native_surface = source;
    require(enumerate_adapters(Backend::Vulkan, options).diagnostic.code ==
                "native_surface_extensions_invalid",
            "native surface extension count is bounded");
    source.vulkanInstanceExtensions = {"VK_KHR_xcb_surface"};
    options.native_surface = source;
    require(enumerate_adapters(Backend::Vulkan, options).diagnostic.code ==
                "native_surface_extension_missing",
            "native surface VK_KHR_surface requirement");
    source.vulkanInstanceExtensions = {
        std::string("VK_KHR_surface\0bad", 18U)};
    options.native_surface = source;
    require(create_device(Backend::Vulkan, options).diagnostic.code ==
                "native_surface_extension_name_invalid",
            "native surface extension names reject embedded NUL bytes");

    options.native_surface.reset();
    options.headless = true;
    options.allow_software = false;
    options.prefer_software = true;
    require(enumerate_adapters(Backend::Vulkan, options).status == DeviceStatus::invalid_options,
            "contradictory software adapter options");
}

void contract_presentation_target() {
    using namespace apex::render;
    Diagnostic diagnostic;
    PresentationTargetDescription description;
    require(validate_presentation_target_description(description, diagnostic) ==
                PresentationTargetStatus::invalid_description &&
                diagnostic.code == "presentation_dimensions_invalid",
            "zero-sized presentation target rejected");

    description.width = 640U;
    description.height = 480U;
    for (const TextureFormat format : {TextureFormat::rgba8_unorm,
                                       TextureFormat::rgba8_srgb,
                                       TextureFormat::bgra8_unorm,
                                       TextureFormat::bgra8_srgb}) {
        description.format = format;
        require(validate_presentation_target_description(description, diagnostic) ==
                    PresentationTargetStatus::ready && diagnostic.code.empty(),
                "portable presentation format accepted");
    }

    description.width = max_texture_dimension + 1U;
    require(validate_presentation_target_description(description, diagnostic) ==
                PresentationTargetStatus::invalid_description &&
                diagnostic.code == "presentation_dimension_limit",
            "oversized presentation target rejected");
    description.width = 640U;
    description.image_count = 1U;
    require(validate_presentation_target_description(description, diagnostic) ==
                PresentationTargetStatus::invalid_description &&
                diagnostic.code == "presentation_image_count_invalid",
            "single-buffered presentation target rejected");
    description.image_count = max_presentation_image_count + 1U;
    require(validate_presentation_target_description(description, diagnostic) ==
                PresentationTargetStatus::invalid_description &&
                diagnostic.code == "presentation_image_count_invalid",
            "over-budget presentation image count rejected");
    description.image_count = 2U;
    description.format = TextureFormat::bc1_srgb;
    require(validate_presentation_target_description(description, diagnostic) ==
                PresentationTargetStatus::unsupported &&
                diagnostic.code == "presentation_format_unsupported",
            "block-compressed presentation target rejected");
}

